"""Build the static lecture with Python 3 standard library only."""
import html,json,re
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
S=json.loads((ROOT/'src/lessons.json').read_text())
W=json.loads((ROOT/'src/writing.json').read_text())
assert len(S)==len(W)==42
esc=html.escape
NAV='<header class="topbar"><a class="brand" href="../index.html">文献阅读 / Regulating Conglomerates</a><nav class="toplinks"><a href="index.html">逐页讲义</a><a class="always" href="writing-workshop.html">写作工作坊</a><a href="presentation.html">课堂演示</a><a href="script.html">逐字稿</a></nav></header>'
def doc(title,body,script=''):
 return '<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#101012"><meta name="description" content="Regulating Conglomerates 的 42 页中文在线讲义，含逐字稿、逐页研究与写作拆解、两厂模型工作坊和论文写作练习。"><title>'+title+'</title><link rel="stylesheet" href="lecture.css"></head><body>'+body+(f'<script src="{script}"></script>' if script else '')+'</body></html>'
def writing_html(w):
 return '<dl><dt><span>01</span>这一页在论证中做什么</dt><dd>'+esc(w['role'])+'</dd><dt><span>02</span>为什么要接到下一步</dt><dd>'+esc(w['bridge'])+'</dd><dt><span>03</span>如果从零开始，怎样扩展</dt><dd>'+esc(w['build'])+'</dd><dt><span>04</span>可以怎样组织成段落</dt></dl><blockquote class="example"><p>'+esc(w['example'])+'</p><small>教学性重写，不是作者原句，也不是对真实研究顺序的还原。</small></blockquote><p class="pitfall"><b>容易写错：</b>'+esc(w['pitfall'])+'</p>'
sections=[];toc=[];last='';md='# 《监管企业集团》逐页研究与写作拆解\n\n这是一份教学性分析，区分论文实际论证、可借鉴的方法和独立教学示范。不是作者真实研究过程的还原。\n\n'
for i,(s,w) in enumerate(zip(S,W),1):
 if s['section']!=last:toc.append('<p class="nav-section">'+esc(s['section'])+'</p>');last=s['section']
 toc.append(f'<a href="#lesson-{i}" data-page="{i}"><span class="navno">{i:02d}</span>{esc(s["title"])}</a>')
 prev=f'<a href="#lesson-{i-1}">← {esc(S[i-2]["title"])}</a>' if i>1 else '<a href="#overview">← 讲义首页</a>'
 nxt=f'<a href="#lesson-{i+1}">{esc(S[i]["title"])} →</a>' if i<42 else '<a href="writing-workshop.html">进入写作工作坊 →</a>'
 notes=''.join('<p>'+esc(p)+'</p>' for p in s['notes'].split('\n'))
 section=f'''<article id="lesson-{i}" class="lesson" data-title="{esc(s['title'])}"><header class="lesson-head"><p class="eyebrow">第 {i:02d} / 42 页 · {esc(s['section'])}</p><h1>{esc(s['title'])}</h1><p class="subtitle">{esc(s['sub'])}</p><p class="small"><a href="presentation.html#{i}">在演示稿中打开此页 ↗</a></p></header><p class="section-label paper-label">理解文章</p><div class="paper-content">{s['body']}</div><p class="source paper-source">原文定位：{esc(s['source'])}</p><details class="notes" open><summary>这一页怎么讲 · 完整逐字稿</summary><div class="speech">{notes}</div></details><section class="writing" id="writing-{i}"><p class="section-label">学习研究与写作</p><h2>这一页，怎样发展成论文的一部分？</h2><p class="note-label">从论证功能到可以亲手完成的写作任务</p>{writing_html(w)}<div class="exercise"><h3>05　换成你的题目，写一小段</h3><label for="exercise-{i}">{esc(w['exercise'])}</label><textarea id="exercise-{i}" data-exercise="{i}" placeholder="不必一次写完。先写清楚一个问题、一项证据，或一句过渡。"></textarea><div class="exercise-actions"><span class="save-status" role="status">仅保存在当前浏览器，不会上传。</span><button class="quiet" data-export>导出全部练习</button></div></div></section><nav class="lesson-bottom" aria-label="逐页导航">{prev}<button class="quiet visited-toggle" data-page="{i}" aria-pressed="false">标记本页学完</button>{nxt}</nav></article>'''
 sections.append(section)
 md+=f'## 第 {i:02d} 页：{s["title"]}\n\n'
 for k,label in [('role','论证任务'),('bridge','证据衔接'),('build','从零扩展'),('example','段落示范'),('pitfall','容易写错'),('exercise','写作练习')]:md+=f'### {label}\n\n{w[k]}\n\n'
 md+='原文定位：'+s['source']+'\n\n---\n\n'
welcome='''<section class="welcome" id="overview"><header class="hero"><p class="eyebrow">读懂一篇论文，也学会把自己的研究写完整</p><h1>监管企业集团<br>研究与写作在线讲义</h1><p class="intro">从“一家大厂少用了煤”开始，理解作者怎样追踪生产去了哪里，怎样建立可验证的模型，最后形成有边界的政策结论。</p><p class="small">Chen, Chen, Liu, Suárez Serrato &amp; Xu · American Economic Review, 2025</p><div class="actions"><a href="#lesson-1">开始第 1 页</a><a href="writing-workshop.html">从零搭建研究</a><a id="resume" hidden href="#lesson-1">继续上次阅读</a></div></header><div class="route-grid"><div><h3>准备课堂汇报</h3><p>42 页内容与演示稿逐页对应。先读本页重点，再用完整逐字稿练习讲解。前 34 页为正文，后 8 页用于答辩。</p><a href="presentation.html">打开演示稿 ↗</a></div><div><h3>学习论文写作</h3><p>每页都拆开论证任务、证据衔接、从零扩展、段落示范和练习。可以只显示写作内容，也可以对照原有讲解。</p><a href="#lesson-1-writing">从第一页的研究问题开始 ↗</a></div></div><div class="disclosure">“写丰满”是补足一个结论所需的证据。逐页示范属于教学分析，并不声称还原作者真实的研究过程。工作坊中的两厂模型是独立教学推导。</div><h2>这份讲义可以怎么用</h2><p>第一遍沿正文理解经济机制。第二遍切换“专看写作”，观察每一节如何提出下一节的问题。第三遍在练习框里换成自己的题目，导出一份研究草稿。练习与阅读进度只存在当前浏览器，跨设备不会同步。</p><p><a href="script.html">阅读与打印完整逐字稿及写作拆解</a>　<a href="writing-notes.md" download>下载写作拆解 Markdown</a></p></section>'''
sidebar='<aside class="sidebar" id="sidebar" aria-label="讲义目录"><a href="#overview">讲义首页</a><h2>42 页阅读目录</h2><input id="navSearch" type="search" aria-label="搜索页标题" placeholder="搜索页标题"><p class="reading-status" id="readStatus">已标记学完 0 / 42 页</p><div class="progress-track"><div id="progressBar"></div></div>'+''.join(toc)+'<p><a href="writing-workshop.html">从两厂模型到完整论文 ↗</a></p></aside>'
controls='<div class="view-controls" aria-label="阅读模式"><button id="viewFull" class="quiet" aria-pressed="true">内容 + 写作</button><button id="viewWriting" class="quiet" aria-pressed="false">专看写作</button><button class="quiet" data-export>导出练习</button><button class="quiet" data-print>打印讲义</button></div>'
footer='<footer class="bottom-footer">内容依本地论文稿本与在线附录核对。<a href="https://www.aeaweb.org/articles?id=10.1257/aer.20211455">官方论文与附录</a>。量化结果保留原文口径，写作示范与教学模型另行标注。<br>快捷键：Alt + 左右方向键切换页面。打印会输出全部 42 页对应内容，“专看写作”模式可仅打印写作部分。</footer>'
nav=NAV.replace('<nav class="toplinks">','<button id="menu" class="mobile-menu quiet" aria-expanded="false" aria-controls="sidebar">目录</button><nav class="toplinks">')
(ROOT/'index.html').write_text(doc('监管企业集团 · 研究与写作在线讲义','<a class="skip-link" href="#main">跳到正文</a>'+nav+'<div class="layout">'+sidebar+'<main class="main" id="main">'+controls+welcome+''.join(sections)+footer+'</main></div>','lecture.js'))
workshop=(ROOT/'src/workshop-body.html').read_text()
(ROOT/'writing-workshop.html').write_text(doc('从两厂模型到完整论文 · 研究设计工作坊',NAV+'<main class="workshop">'+workshop+footer+'</main>','workshop.js'))
# A print-friendly, fully static companion. Remove editable fields, keep prompts.
script=''.join(sections)
script=re.sub(r'<textarea.*?</textarea>','',script,flags=re.S)
script=re.sub(r'<div class="exercise-actions">.*?</div>','',script,flags=re.S)
script=re.sub(r'<nav class="lesson-bottom".*?</nav>','',script,flags=re.S)
script=script.replace('class="exercise"','class="print-exercise"')
script_intro='<header class="hero"><p class="eyebrow">备课与写作手册</p><h1>42 页逐字稿<br>与研究写作拆解</h1><p class="intro">每页依次阅读内容、完整逐字稿和写作拆解。打印时为浅色页面，便于纸面批注。</p><button onclick="window.print()">打印 / 另存为 PDF</button><p><a href="index.html">进入逐页交互讲义</a>　<a href="writing-workshop.html">研究设计工作坊</a></p></header>'
(ROOT/'script.html').write_text(doc('逐字稿与写作拆解 · 可打印',NAV+'<main class="workshop">'+script_intro+script+'</main>'))
(ROOT/'writing-notes.md').write_text(md)
# Add writing drawer to every original slide and unify its color theme.
base=(ROOT/'src/presentation.base.html').read_text()
styles='''
:root{--paper:#151517;--ink:#eee9df;--green:#d7b677;--red:#e4a7b7;--muted:#b4ada4;--line:#433a30}body{background:#0b0b0d}.dark{background:#101012;color:#eee9df}.dark .kicker,.dark .takeaway{color:#e5c88f}.dark .subtitle,.dark .slide-footer{color:#b4ada4}.dark .slide-footer,.dark .takeaway{border-color:#433a30}.cover-question{color:#e5c88f}.figure{border:7px solid #e7e3da;border-radius:2px}.kicker{color:#d7b677}.lab-result{background:#282219}#toolbar{background:#0b0b0e;color:#e5cc98}button,select{background:#242025;border-color:#665241;color:#f0dbb3}button:hover{background:#3b3034}#notes,#toc{background:#18171a;color:#eee9df;border-color:#433a30}#toc input{background:#232025;color:#eee9df;border:1px solid #6b575f}#tocList button:hover{background:#30282b}#tocList button{color:#eee9df}body.speaker #speakerUI{background:#171618;color:#eee9df}#speakerOutline{color:#bfb5aa}#speakerSource{color:#c0b2a6}.slide-footer{color:#b4ada4}#notes .meta{color:#b4ada4}.lab input{accent-color:#d7b677}#writingNotes{display:none;position:fixed;right:0;top:0;bottom:56px;width:500px;background:#19171b;color:#eee9df;padding:28px;overflow:auto;border-left:1px solid #665241;font-size:17px;line-height:1.9;z-index:12}body.writing-open #writingNotes{display:block}body.writing-open #stage{right:500px}#writingNotes h2{color:#e5c88f;font-size:24px}#writingNotes h3{color:#e4acbd;font-size:18px;margin:27px 0 6px}#writingNotes a{color:#d7b677}#writingNotes .writing-example{border-left:2px solid #e4acbd;padding-left:18px}#writingNotes .small{font-size:13px;color:#baafa7}@media(max-width:900px){body.writing-open #stage{right:0;bottom:48vh}body.writing-open #writingNotes{width:100%;top:52vh;bottom:56px}}@media print{:root{--ink:#172e30;--green:#715326;--muted:#5f655e;--line:#c8cec5}#writingNotes{display:none!important}.figure{border:0}.slide{color:#172e30!important}.cover-question,.dark .kicker,.dark .takeaway{color:#715326}.slide-footer,.dark .slide-footer{color:#5f655e}.lab-result{background:#eee9df}}
'''
base=base.replace('</head>','<style>'+styles+'</style></head>')
base=base.replace('<button id="fullscreen"','<button id="writingToggle" data-hide-speaker aria-pressed="false">写作 W</button><button id="fullscreen"')
base=base.replace('<div id="blank"','<aside id="writingNotes" aria-label="逐页研究与写作拆解"></aside><div id="blank"')
js='''
const writingLessons=JSON.parse(document.getElementById('writingData').textContent);function writingEscape(s){const e=document.createElement('div');e.textContent=s;return e.innerHTML}function updateWriting(){const w=writingLessons[current],el=document.getElementById('writingNotes');el.innerHTML='<p class="small">第 '+(current+1)+' 页 · 研究与写作拆解</p><h2>'+writingEscape(data[current].title)+'</h2>'+[['这一页的论证任务','role'],['如何接到下一步','bridge'],['从零开始怎样扩展','build'],['段落示范','example'],['容易写错','pitfall'],['写作练习','exercise']].map(([label,key])=>'<h3>'+label+'</h3><p class="'+(key==='example'?'writing-example':'')+'">'+writingEscape(w[key])+'</p>').join('')+'<p class="small">教学分析与示范，不是作者原句或真实研究过程的还原。</p><p><a href="index.html#lesson-'+(current+1)+'-writing" target="_blank" rel="noopener">在在线讲义中练习 ↗</a></p>';el.scrollTop=0}function toggleWriting(){document.body.classList.toggle('writing-open');document.body.classList.remove('notes');document.getElementById('notesToggle').setAttribute('aria-pressed','false');document.getElementById('writingToggle').setAttribute('aria-pressed',document.body.classList.contains('writing-open'));fit()}const showBeforeWriting=show;show=function(n,send=true){showBeforeWriting(n,send);updateWriting()};document.getElementById('writingToggle').onclick=toggleWriting;document.getElementById('notesToggle').addEventListener('click',()=>{document.body.classList.remove('writing-open');document.getElementById('writingToggle').setAttribute('aria-pressed','false');fit()});window.addEventListener('keydown',e=>{if(e.target.matches('input,textarea,select'))return;if(e.key.toLowerCase()==='w'&&!isSpeaker)toggleWriting();if(e.key.toLowerCase()==='n'){document.body.classList.remove('writing-open');document.getElementById('writingToggle').setAttribute('aria-pressed','false');fit()}});updateWriting();
'''
base=base.replace('</body>','<script id="writingData" type="application/json">'+json.dumps(W,ensure_ascii=False).replace('</','<\\/')+'</script><script>'+js+'</script></body>')
(ROOT/'presentation.html').write_text(base)
print('Built 42 lessons, 42 writing sections, workshop, presentation, and print companion.')
